#!/usr/bin/env bash
# Setup script for orpheus_sim TPC-H benchmark
#
# Creates the orpheus_sim schema, loads TPC-H data, and initializes versioning.
# Assumes TPC-H data has already been generated by bench/tpch/setup.sh

set -euo pipefail

HERE="$(cd "$(dirname "$0")" && pwd)"
TPCH_DIR="$(cd "$HERE/../tpch" && pwd)"
DB="${DB:-postgres}"

if [ ! -d "$TPCH_DIR/data" ]; then
    echo "error: TPC-H data not found in $TPCH_DIR/data" >&2
    echo "Run 'cd bench/tpch && ./setup.sh' first" >&2
    exit 1
fi

echo "==> Creating orpheus_sim schema..."
psql -q "$DB" -f "$HERE/schema.sql" 2>&1 || {
    echo "error: failed to create schema" >&2
    exit 1
}

echo "==> Loading TPC-H data..."
# Update the load.sql COPY commands to find data correctly
# We need to adjust paths relative to where psql is run
cd "$HERE"
psql -q "$DB" -f load.sql 2>&1 || {
    echo "error: failed to load data" >&2
    exit 1
}

echo "==> Initializing versioning..."
psql -q "$DB" -f init_sim.sql 2>&1 || {
    echo "error: failed to initialize versioning" >&2
    exit 1
}

echo "==> Setup complete!"
echo ""
echo "Next steps:"
echo "  1. Verify setup: psql -c \"SELECT * FROM list_versions();\" $DB"
echo "  2. Run benchmark: ./run.sh"
